import { setContext, getContext, onDestroy } from "svelte";
import type { CodeBlockData, CodeBlockHighlightLines, CodeBlockTheme } from "./index.js";

const CONTEXT_ID = "code-block-context";

class UseCompCtx {
	/** Decoded code to display and copy, with its language source and optional header `title` */
	data: CodeBlockData = $state({ code: "", lang: "bash" });
	/** Size shared by the header and code */
	size: UiSize = $state("md");
	/** Highlight theme shared with the code */
	theme: CodeBlockTheme = $state("auto");
	/** Lines to highlight, shared with the code */
	highlightLines: CodeBlockHighlightLines = $state([]);
	isCopying = $state(false);
	copyTimeout?: ReturnType<typeof setTimeout>;

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
		// Clear the copied-state timeout when the code block unmounts.
		onDestroy(() => clearTimeout(this.copyTimeout));
	}

	/** Copies the code to the clipboard and shows the copied state for one second. */
	async copyCode() {
		this.isCopying = true;
		try {
			await navigator.clipboard.writeText(this.data.code);
		} catch {
			// If the clipboard is unavailable or blocked: reset right away instead of showing success.
			this.isCopying = false;
			return;
		}
		clearTimeout(this.copyTimeout);
		this.copyTimeout = setTimeout(() => (this.isCopying = false), 1000);
	}
}

export type CompCtxProps = Pick<InstanceType<typeof UseCompCtx>, "data" | "size" | "theme" | "highlightLines">;

export const setCompCtx = (props: CompCtxProps) => setContext(CONTEXT_ID, new UseCompCtx(props));

export const useCompCtx = () => getContext<ReturnType<typeof setCompCtx>>(CONTEXT_ID);

import type { AvailableShikiLangs } from "./core.js";

export { default as CodeBlock } from "./_.svelte";
export { default as CodeBlockCode } from "./code.svelte";
export { default as CodeBlockHeader } from "./header.svelte";
export { encodeAndDecodeString } from "./core.js";

/** Code to display and copy, with either a file `path` for language detection or an explicit Shiki `lang` */
export type CodeBlockData = { code: string; lang: AvailableShikiLangs; title?: string } | { code: string; path: string; title?: string };

/** Highlight theme: `auto` follows the `.dark` class on an ancestor, while `light` and `dark` force one theme */
export type CodeBlockTheme = "auto" | "light" | "dark";

/** 1-based lines to highlight, as an array such as `[2, 4]` or a range string such as `"1,3-5"` */
export type CodeBlockHighlightLines = number[] | string;

/** Code block root that shares its data with the header and code */
export interface Props extends CompPropsWithChild<"div"> {
	/** Header, code display, or other content */
	children: CompPropsWithChild<"div">["children"];
	/** Code and language metadata; `title` takes precedence over the header path label */
	data: CodeBlockData;
	/** Decodes `data.code` from UTF-8 Base64 before display and copying; malformed Base64 throws during decoding */
	usingEncodedData?: boolean;
	/** Highlight theme shared with the code; defaults to `auto`, which follows the `.dark` class on an ancestor */
	theme?: CodeBlockTheme;
	/** Lines to highlight, such as `[2, 4]` or `"1,3-5"`; shared with the code */
	highlightLines?: CodeBlockHighlightLines;
	/** Header height, code padding, and font size */
	size?: UiSize;
	/** Corner radius; follows `size` when omitted. `pill` is a true pill that can clip the content, so use `3xl` or `4xl` to stay round */
	rounded?: UiRounded;
	/** Classes merged onto the root container */
	class?: CompPropsWithChild<"div">["class"];
}

/** Code block header with the file label and copy button */
export interface HeaderProps extends CompProps<"header"> {
	/** Header label used after `data.title` and before `data.path`; a nonempty value also shows the header */
	path?: string;
	/** Classes merged onto the header */
	class?: CompProps<"header">["class"];
}

/** Highlighted code display */
export interface CodeProps extends CompProps<"div"> {
	/** Highlight theme; overrides the code block's `theme` */
	theme?: CodeBlockTheme;
	/** Lines to highlight, such as `[2, 4]` or `"1,3-5"`; overrides the code block's `highlightLines` */
	highlightLines?: CodeBlockHighlightLines;
	/** Classes merged onto the code container */
	class?: CompProps<"div">["class"];
}

export type CodeBlockProps = Props;
export type CodeBlockHeaderProps = HeaderProps;
export type CodeBlockCodeProps = CodeProps;

import { createJavaScriptRegexEngine } from "shiki/engine/javascript";
import { createHighlighterCoreSync } from "shiki/core";
import typescriptLang from "@shikijs/langs/typescript";
import svelteLang from "@shikijs/langs/svelte";
import jsonLang from "@shikijs/langs/json";
import bashLang from "@shikijs/langs/bash";
import markdownLang from "@shikijs/langs/markdown";
import cssLang from "@shikijs/langs/css";
import darkTheme from "@shikijs/themes/dark-plus";
import lightTheme from "@shikijs/themes/light-plus";
import type { ShikiTransformer } from "shiki/core";
import type { CodeBlockHighlightLines } from "./index.js";
export const availableShikiLangs = ["typescript", "svelte", "json", "css", "bash", "markdown"] as const;
export type AvailableShikiLangs = (typeof availableShikiLangs)[number];

/** Theme backgrounds */
export const themeBg = { dark: "#18181b", light: "#fcfcfc" };

// Patch themes with your custom backgrounds
export const vsDarkTheme = {
	...darkTheme,
	name: "vscode-dark", // must match what shikiToMonaco registers
	bg: themeBg.dark,
	colors: { ...darkTheme.colors, "editor.background": themeBg.dark },
};

export const vsLightTheme = {
	...lightTheme,
	name: "vscode-light",
	bg: themeBg.light,
	colors: { ...lightTheme.colors, "editor.background": themeBg.light },
};

const globalShiki = globalThis as typeof globalThis & { __shikiHighlighter?: ReturnType<typeof createHighlighterCoreSync> };

/** A preloaded highlighter instance (available themes: vscode-dark and vscode-light) */
export const shikiHighlighter = (globalShiki.__shikiHighlighter ??= createHighlighterCoreSync({
	themes: [vsDarkTheme, vsLightTheme],
	langs: [typescriptLang, svelteLang, jsonLang, bashLang, markdownLang, cssLang],
	engine: createJavaScriptRegexEngine(),
}));

/** Get file lang from file path */
export const getFileLangFromPath = (filePath: string): AvailableShikiLangs => {
	const fileExt = filePath?.split(".").pop()?.toLowerCase() || "";
	const langMap: Record<string, AvailableShikiLangs> = {
		ts: "typescript",
		js: "typescript",
		css: "css",
		bash: "bash",
		svelte: "svelte",
		json: "json",
		md: "markdown",
		typescript: "typescript",
		javascript: "typescript",
		markdown: "markdown",
	};
	return langMap[fileExt] || null;
};

/** Encode and decode string data */
export function encodeAndDecodeString(data: string, action: "encode" | "decode") {
	// Encode string
	if (action == "encode") return btoa(String.fromCharCode(...new TextEncoder().encode(data)));
	// Decode string
	return new TextDecoder().decode(Uint8Array.from(atob(data), (char) => char.charCodeAt(0)));
}

/** Get the 1-based line numbers to highlight from an array or a range string, such as `"1,3-5"`, clamped to the line count */
export const getHighlightedLines = (lines: CodeBlockHighlightLines, lineCount: number) => {
	const highlighted = new Set<number>();
	// Split a string into comma-separated lines and ranges, and treat an array as single lines.
	const parts = typeof lines === "string" ? lines.split(",") : lines.map(String);
	for (const part of parts) {
		const [start, end = start] = part.split("-").map((value) => Number.parseInt(value.trim(), 10));
		// Skip invalid parts, such as `a`, `3-`, or `-2`.
		if (!Number.isInteger(start) || !Number.isInteger(end)) continue;
		// Clamp to the code so a huge range from streamed text stays cheap, and accept reversed ranges such as `5-3`.
		const to = Math.min(lineCount, Math.max(start, end));
		for (let line = Math.max(1, Math.min(start, end)); line <= to; line++) highlighted.add(line);
	}
	return highlighted;
};

/** Shiki transformer that adds the `highlighted` class to each listed line */
export const lineHighlightTransformer = (lines: Set<number>): ShikiTransformer => ({
	name: "code-block-line-highlight",
	line(node, line) {
		// If the line is listed: mark it so the code styles can highlight it.
		if (lines.has(line)) this.addClassToHast(node, "highlighted");
	},
});

/** Read `{1,3-5}` line highlights from a code fence info string, and return the info string without them */
export const getHighlightLinesFromInfo = (info: string) => {
	const match = info.match(/\{([\d\s,-]*)\}/);
	// If the info string has no highlights: return it as is.
	if (!match) return { highlightLines: "", info: info.trim() };
	return { highlightLines: match[1].replace(/\s+/g, ""), info: info.replace(match[0], "").trim() };
};
